 ACCOUNT_CREATED_DATE date NOT NULL COMMENT 'Date when customer account was created.',
 ACCOUNT_CLOSED_DATE  date COMMENT 'Date when customer account was closed (null if active).',
 IS_ACTIVE            boolean NOT NULL COMMENT 'Flag indicating if customer account is currently active.',

 CONSTRAINT PK_1 PRIMARY KEY ( CUSTOMER_ID ),
